    <script>
        document.addEventListener('DOMContentLoaded', function() {
            function adjustLayout() {
                const navbar = document.querySelector('nav, header, .navbar');
                const header = document.getElementById('fixed-header');
                const tabs = document.getElementById('fixed-tabs');
                const container = document.getElementById('main-container');
                if (navbar && header && tabs && container) {
                    const navbarHeight = navbar.offsetHeight;
                    header.style.top = navbarHeight + 'px';
                    const headerHeight = header.offsetHeight;
                    tabs.style.top = (navbarHeight + headerHeight) + 'px';
                    const tabsHeight = tabs.offsetHeight;
                    container.style.paddingTop = (headerHeight + tabsHeight + 40) + 'px';
                    const sidebar = document.querySelector('.sticky');
                    if (sidebar) {
                        sidebar.style.top = (navbarHeight + headerHeight + tabsHeight + 20) + 'px';
                    }
                }
            }
            adjustLayout();
            window.addEventListener('resize', adjustLayout);
            window.addEventListener('load', adjustLayout);
        });
        document.querySelectorAll('a[href^="?tab="]').forEach(tab => {
            tab.addEventListener('click', function(e) {
                document.querySelectorAll('a[href^="?tab="]').forEach(t => {
                    t.classList.remove('text-orange-600', 'border-b-4', 'border-orange-600');
                    t.classList.add('text-gray-600', 'hover:text-orange-500');
                });
                this.classList.add('text-orange-600', 'border-b-4', 'border-orange-600');
                this.classList.remove('text-gray-600', 'hover:text-orange-500');
            });
        });
        document.querySelectorAll('.hover\\:bg-gray-50').forEach(item => {
            item.addEventListener('mouseenter', () => {
                item.style.transform = 'translateY(-2px)';
                item.style.boxShadow = '0 4px 12px rgba(0,0,0,0.1)';
            });
            item.addEventListener('mouseleave', () => {
                item.style.transform = 'translateY(0)';
                item.style.boxShadow = 'none';
            });
        });
    </script>
